import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Social Authentication & OAuth2 (Google & GitHub)","description":"","frontmatter":{},"headers":[],"relativePath":"en/08-social-auth-oauth2.md","filePath":"en/08-social-auth-oauth2.md"}'),n={name:"en/08-social-auth-oauth2.md"};function o(r,a,l,p,h,c){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="social-authentication-oauth2-google-github" tabindex="-1">Social Authentication &amp; OAuth2 (Google &amp; GitHub) <a class="header-anchor" href="#social-authentication-oauth2-google-github" aria-label="Permalink to &quot;Social Authentication &amp; OAuth2 (Google &amp; GitHub)&quot;">​</a></h1><blockquote><p><strong>One-click secure login, automatic email-based account linking, and 100% offline development support.</strong></p></blockquote><hr><h2 id="_1-architecture-overview" tabindex="-1">1. Architecture Overview <a class="header-anchor" href="#_1-architecture-overview" aria-label="Permalink to &quot;1. Architecture Overview&quot;">​</a></h2><p>SoftForge features an <strong>OAuth2 Authorization Code Flow</strong> built for security, privacy, and full developer autonomy:</p><ul><li><strong>Built-in Providers:</strong> Ready-to-use adapters for <strong>Google</strong> and <strong>GitHub</strong>.</li><li><strong>Smart Account Linking (Auto-Linking):</strong> If an existing user registered via password, logging in via OAuth with the same verified email automatically links the OAuth provider to their existing profile without losing data.</li><li><strong>Dedicated <code>oauth_accounts</code> Table:</strong> One user can link multiple OAuth providers simultaneously with a unique constraint on <code>(provider, provider_user_id)</code>.</li><li><strong>Nullable Password:</strong> OAuth-created users have <code>hashed_password = null</code> and can optionally set a password later.</li><li><strong>Dual Session Mechanism:</strong> Sets <code>HttpOnly</code> security cookies and returns standard Bearer JWT tokens in the JSON response payload.</li><li><strong>Seamless Offline Mock:</strong> During local development or offline test runs, codes prefixed with <code>mock-</code> or missing client secrets automatically return synthetic profiles without network timeouts.</li></ul><hr><h2 id="_2-oauth2-flow-diagram" tabindex="-1">2. OAuth2 Flow Diagram <a class="header-anchor" href="#_2-oauth2-flow-diagram" aria-label="Permalink to &quot;2. OAuth2 Flow Diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    autonumber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    actor User as User / Browser</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Web as Frontend (React + Vite)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant API as SoftForge API (/auth)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Provider as Google / GitHub</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as PostgreSQL Database</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    User-&gt;&gt;Web: Clicks &quot;Sign in with Google&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Web-&gt;&gt;API: GET /api/v1/auth/oauth/google/authorize</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;Web: Returns authorization_url and CSRF state</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Web-&gt;&gt;Provider: Redirects user to consent screen</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Provider--&gt;&gt;Web: Redirects back with ?code=...&amp;state=...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Web-&gt;&gt;API: GET /api/v1/auth/oauth/google/callback?code=...&amp;state=...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;Provider: Exchanges code for token &amp; profile (or offline mock)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Provider--&gt;&gt;API: Returns email, provider_user_id, avatar_url, name</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;DB: Looks up user by email or existing oauth_account</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    alt User does not exist</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        API-&gt;&gt;DB: Creates new User and oauth_accounts entry</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    else User exists without link</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        API-&gt;&gt;DB: Links oauth_account to existing user</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;DB: Generates session refresh_token</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;Web: Returns access_token, refresh_token and sets HttpOnly cookies</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Web-&gt;&gt;User: Redirects to dashboard</span></span></code></pre></div><hr><h2 id="_3-endpoints" tabindex="-1">3. Endpoints <a class="header-anchor" href="#_3-endpoints" aria-label="Permalink to &quot;3. Endpoints&quot;">​</a></h2><h3 id="get-api-v1-auth-oauth-provider-authorize" tabindex="-1"><code>GET /api/v1/auth/oauth/{provider}/authorize</code> <a class="header-anchor" href="#get-api-v1-auth-oauth-provider-authorize" aria-label="Permalink to &quot;\`GET /api/v1/auth/oauth/{provider}/authorize\`&quot;">​</a></h3><p>Generates authorization URL with CSRF protection.</p><ul><li><strong>Path Parameters:</strong> <code>provider</code> (<code>google</code> or <code>github</code>).</li><li><strong>Query Params:</strong> <code>redirect_uri</code> (optional).</li></ul><h3 id="get-api-v1-auth-oauth-provider-callback" tabindex="-1"><code>GET /api/v1/auth/oauth/{provider}/callback</code> <a class="header-anchor" href="#get-api-v1-auth-oauth-provider-callback" aria-label="Permalink to &quot;\`GET /api/v1/auth/oauth/{provider}/callback\`&quot;">​</a></h3><p>Validates code, retrieves user profile, creates or links account, and returns session tokens.</p><ul><li><strong>Path Parameters:</strong> <code>provider</code> (<code>google</code> or <code>github</code>).</li><li><strong>Query Params:</strong> <code>code</code>, <code>state</code>.</li></ul><hr><h2 id="_4-environment-variables" tabindex="-1">4. Environment Variables <a class="header-anchor" href="#_4-environment-variables" aria-label="Permalink to &quot;4. Environment Variables&quot;">​</a></h2><p>In <code>apps/api/.env</code>:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FRONTEND_URL=http://localhost:5173</span></span>
<span class="line"><span>GOOGLE_CLIENT_ID=your_google_client_id</span></span>
<span class="line"><span>GOOGLE_CLIENT_SECRET=your_google_client_secret</span></span>
<span class="line"><span>GITHUB_CLIENT_ID=your_github_client_id</span></span>
<span class="line"><span>GITHUB_CLIENT_SECRET=your_github_client_secret</span></span></code></pre></div>`,21)])])}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
